FC=ref('FDA: Ferric Carboxymaltose—Boxed Warning for Hypophosphatemia, 2026','https://www.fda.gov/drugs/drug-safety-communications/fda-adds-boxed-warning-labeling-ferric-carboxymaltose-injection-injectafer-describe-risk-low')
